index 3ec62f9..eca22eb 100644
--- a/src/lib.c
+++ b/src/lib.c
@@ -591,11 +591,10 @@ void dav1d_flush(Dav1dContext *const c) {

     c->mastering_display = NULL;
     c->content_light = NULL;
+    c->itut_t35 = NULL;
